from math import comb

def get_total_number_of_sequences(m, n):
    # Initialize DP table
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Base case
    dp[1][1] = 1

    # Fill the DP table
    for i in range(2, m + 1):
        for j in range(1, n + 1):
            dp[i][j] = dp[i - 1][j] + dp[i // 2][j - 1]

    return dp[m][n]

