def max_sub_array_sum_repeated(arr, n, k):
    def kadane(arr):
        max_so_far = -sys.maxsize - 1
        max_ending_here = 0
        for i in arr:
            max_ending_here += i
            if max_so_far < max_ending_here:
                max_so_far = max_ending_here
            if max_ending_here < 0:
                max_ending_here = 0
        return max_so_far

