        return kadane(arr)

    max_kadane = kadane(arr)
    max_prefix_sum = max(arr)
    max_suffix_sum = max(arr[::-1])

    if k > 2:
        return max_kadane + (k - 2) * (sum(arr) + max_suffix_sum + max_prefix_sum)
    else:
        return max_kadane + sum(arr)

